setup:
python3 - <<'EOF'
import json, urllib.request
H = {'User-Agent': 'probe', 'Accept': 'application/vnd.github+json'}
url = 'https://api.github.com/repos/astanin/python-tabulate/actions/workflows/tabulate.yml/runs?per_page=5'
try:
    d = json.load(urllib.request.urlopen(urllib.request.Request(url, headers=H), timeout=30))
    with open('/tmp/ci_runs.txt', 'w') as f:
        for r in d['workflow_runs']:
            f.write(f"{r['name']} branch={r['head_branch']} sha={r['head_sha'][:8]} status={r['status']} conclusion={r['conclusion']} created={r['created_at']}\n")
except Exception as e:
    open('/tmp/ci_runs.txt', 'w').write(f'API_FETCH_FAILED: {e}\n')
EOF
